INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S01','勒索病毒攻击演练','基础版','重大',NULL,'启用','v2.0','2026-11-05',18,'内网终端中招、文件加密、勒索提示，评估HIS服务器感染风险，推演断网隔离、备份恢复与上报流程。','T+0 监控平台推送紧急告警：HIS 门诊工作站与共享文件服务器出现大量文件被加密（扩展名变为 .locked），桌面弹出勒索信；已有 3 台终端无法打开业务系统，疑似勒索病毒正在院内网横向扩散。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S02','内网横向渗透/账号泄露','基础版','较大',NULL,'启用','v1.5','2026-11-01',16,'弱口令入侵后横向移动，电子病历数据遭非法访问，推演账号排查、终端隔离与取证。','T+0 监测发现电子病历系统存在异常账号登录与批量查询行为：同一账号在 10 分钟内从 4 台不同终端访问病历，疑似弱口令被利用并横向渗透，部分病历数据可能已被非法访问。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S03','DDoS攻击致门诊收费卡顿','基础版','较大',NULL,'启用','v1.5','2026-11-01',16,'门诊收费系统遭流量攻击卡顿，推演流量清洗协调、窗口纸质兜底与业务恢复确认。','T+0 门诊收费系统出现大面积卡顿并间歇性超时，外网出口流量异常激增（峰值约为日常的 30 倍），收费窗口排队积压，疑似遭受 DDoS 流量攻击。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S04','钓鱼邮件跳板入侵','基础版','一般',NULL,'启用','v1.5','2026-11-01',15,'信息科人员点击木马邮件，攻击者获取跳板，推演邮件排查、全员通报与账号重置。','T+0 信息科多名人员收到伪装为“医保结算通知”的邮件并点击附件，随后终端出现可疑外联行为与异常进程，疑似钓鱼木马已在办公终端取得跳板权限。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S05','核心存储故障系统宕机','基础版','重大',NULL,'启用','v1.5','2026-11-01',17,'核心存储/数据库故障致HIS、EMR整体宕机，推演灾备切换、兜底流程与恢复验证。','T+0 核心存储阵列发出硬件告警，HIS、EMR 等业务系统整体无法访问，数据库连接持续失败，门诊挂号、收费与住院医嘱业务中断，需立即启动应急与业务兜底。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S06','患者隐私数据泄露（舆情发酵）','基础版','重大',NULL,'启用','v1.5','2026-11-01',15,'虚拟患者数据在外部论坛售卖引发舆情，推演上报、口径审批、舆情管控与报案取证。','T+0 监测发现虚拟患者数据在外部论坛被公开售卖，样本包含姓名、就诊科室与就诊记录；相关截图已在社交媒体传播，存在舆情快速发酵与监管问责风险。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S07','外网边界防火墙被突破','基础版','较大',NULL,'启用','v1.5','2026-11-01',15,'边界设备被突破、多业务系统并发告警，推演边界收敛、策略调整与全网排查。','T+0 外网边界防火墙检测到异常穿透与策略篡改行为，多个业务系统同时出现异常访问告警，疑似边界设备已被突破并建立外联通道，需立即收敛边界并开展全网排查。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `scenarios` (`id`, `name`, `type`, `level`, `difficulty`, `status`, `version`, `updated`, `nodes`, `descr`, `alert`) VALUES ('S08','恶意代码批量感染办公网','基础版','一般',NULL,'启用','v1.5','2026-11-01',16,'办公网终端批量感染恶意代码，业务网暂未波及，推演批量断网、样本摘要提取与查杀。','T+0 办公网多台终端批量弹出异常进程提示并生成可疑文件，终端资源占用异常升高；业务网暂未发现波及，疑似恶意代码在办公网批量感染。') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `type`=VALUES(`type`), `level`=VALUES(`level`), `difficulty`=VALUES(`difficulty`), `status`=VALUES(`status`), `version`=VALUES(`version`), `updated`=VALUES(`updated`), `nodes`=VALUES(`nodes`), `descr`=VALUES(`descr`), `alert`=VALUES(`alert`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F1','事件初步核实单','[{\"label\":\"发现时间\",\"hint\":\"以监控平台或值班记录中首次发现的时间为准，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"发现方式\",\"hint\":\"如安全告警系统、值班巡检、临床科室报障、外部单位通报。\",\"required\":true,\"type\":\"select\",\"options\":[\"安全告警系统\",\"值班巡检\",\"临床科室报障\",\"外部单位通报\",\"第三方监测\",\"其他\"]},{\"label\":\"报告人\",\"hint\":\"首先发现并报告的人员姓名及所属科室。\",\"required\":true,\"type\":\"text\"},{\"label\":\"受影响主机数量\",\"hint\":\"填写已确认受影响的主机台数，仅演练虚拟数据。\",\"required\":true,\"type\":\"text\"},{\"label\":\"受影响主机清单\",\"hint\":\"按科室/主机名/状态逐条列明，至少含已加密与疑似两类。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"加密文件扩展名\",\"hint\":\"如 .locked、.enc；用于与告警信息比对。\",\"required\":true,\"type\":\"text\"},{\"label\":\"是否仍在加密\",\"hint\":\"选择当前是否仍有终端在写入加密文件。\",\"required\":true,\"type\":\"select\",\"options\":[\"是\",\"否\",\"无法确认\"]},{\"label\":\"是否已隔离\",\"hint\":\"选择受影响主机的隔离进度。\",\"required\":true,\"type\":\"select\",\"options\":[\"是\",\"部分\",\"否\"]},{\"label\":\"共享目录是否受影响\",\"hint\":\"确认共享文件服务器/共享目录是否出现加密文件。\",\"required\":true,\"type\":\"select\",\"options\":[\"是\",\"否\",\"无法确认\"]},{\"label\":\"受影响系统\",\"hint\":\"勾选受到本次事件影响的业务系统，用于驱动业务影响看板变更。\",\"required\":true,\"type\":\"multiselect\",\"options\":[\"HIS收费系统\",\"医护工作站\",\"电子病历系统\",\"临床检验系统\",\"医学影像系统\",\"办公OA系统\"]},{\"label\":\"IP/域名\",\"hint\":\"涉及的主机 IP、域名或访问地址，多个用顿号分隔。\",\"required\":true,\"type\":\"text\"},{\"label\":\"异常现象\",\"hint\":\"客观描述观察到的现象，如文件被加密、异常外联、登录失败激增。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"初步判断\",\"hint\":\"结合告警与现象初判事件类型，注明为模拟核实结论。\",\"required\":true,\"type\":\"select\",\"options\":[\"勒索病毒\",\"其他病毒\",\"误报\",\"待定\"]},{\"label\":\"初步影响范围\",\"hint\":\"已确认受影响的科室、业务和主机数量，未确认的标注「待评估」。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"已采取临时措施\",\"hint\":\"如暂时断开网线、暂停共享目录写入，注明执行人与时间。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"核实人\",\"hint\":\"完成初步核实的信息科值班人员姓名。\",\"required\":true,\"type\":\"text\"},{\"label\":\"核实时间\",\"hint\":\"完成初步核实的时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F10','隔离处置单','[{\"label\":\"隔离时间\",\"hint\":\"完成隔离的时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"隔离主机清单\",\"hint\":\"按主机名/IP/科室逐条列明，仅演练虚拟数据。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"隔离方式\",\"hint\":\"选择实际采用的隔离方式。\",\"required\":true,\"type\":\"select\",\"options\":[\"断网\",\"禁用网卡\",\"交换机端口关闭\",\"ACL限制\"]},{\"label\":\"共享目录处置\",\"hint\":\"确认共享目录写入是否已关闭。\",\"required\":true,\"type\":\"select\",\"options\":[\"已关闭写入\",\"只读\",\"未处置\"]},{\"label\":\"核心服务器处置\",\"hint\":\"说明 HIS/EMR 等核心服务器的处置方式。\",\"required\":true,\"type\":\"select\",\"options\":[\"未动\",\"ACL降权\",\"停机\"]},{\"label\":\"隔离执行人\",\"hint\":\"执行隔离的岗位与人员。\",\"required\":true,\"type\":\"text\"},{\"label\":\"隔离验证\",\"hint\":\"确认受影响主机已无法访问共享与业务。\",\"required\":true,\"type\":\"select\",\"options\":[\"已断网确认\",\"部分确认\",\"未确认\"]},{\"label\":\"证据材料\",\"hint\":\"交换机端口、防火墙 ACL 变更等操作记录名称。\",\"required\":false,\"type\":\"textarea\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F11','备份校验单','[{\"label\":\"恢复点时间\",\"hint\":\"选定的备份恢复点时间。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"恢复点大小\",\"hint\":\"恢复点数据量，如 120GB。\",\"required\":true,\"type\":\"text\"},{\"label\":\"RPO要求\",\"hint\":\"预案要求的数据丢失窗口。\",\"required\":true,\"type\":\"text\"},{\"label\":\"抽验库名\",\"hint\":\"用于可读性抽验的非核心库名称（虚拟）。\",\"required\":true,\"type\":\"text\"},{\"label\":\"可读性验证\",\"hint\":\"抽验表结构与数据是否可读。\",\"required\":true,\"type\":\"select\",\"options\":[\"通过\",\"不通过\",\"未验证\"]},{\"label\":\"不可用备份清单\",\"hint\":\"列出损坏或不可读的恢复点，无则填「无」。\",\"required\":false,\"type\":\"textarea\"},{\"label\":\"校验人\",\"hint\":\"执行备份校验的岗位与人员。\",\"required\":true,\"type\":\"text\"},{\"label\":\"校验时间\",\"hint\":\"完成校验的时间。\",\"required\":true,\"type\":\"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT IGNORE INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F12','事件核实单（通用）','[{\"label\":\"发现时间\",\"hint\":\"以告警平台或值班记录中首次发现的时间为准，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"发现渠道\",\"hint\":\"本次事件的发现来源。\",\"required\":true,\"type\":\"select\",\"options\":[\"安全告警系统\",\"人工巡检\",\"临床科室报告\",\"外部单位通报\",\"第三方监测\",\"其他\"]},{\"label\":\"受影响对象/系统\",\"hint\":\"涉及的系统、主机、账号或业务环节，仅演练虚拟数据。\",\"required\":true,\"type\":\"text\"},{\"label\":\"影响数量\",\"hint\":\"受影响对象数量，如账号数、主机台数。\",\"required\":true,\"type\":\"text\"},{\"label\":\"是否仍在扩散\",\"hint\":\"选择当前是否仍在持续扩散或持续登录。\",\"required\":true,\"type\":\"select\",\"options\":[\"是\",\"否\",\"无法确认\"]},{\"label\":\"临时措施\",\"hint\":\"已采取的临时处置，如限制登录、暂停访问，注明执行人与时间。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"核实人\",\"hint\":\"完成核实的人员姓名与岗位。\",\"required\":true,\"type\":\"text\"},{\"label\":\"核实时间\",\"hint\":\"完成核实的时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"证据材料\",\"hint\":\"支撑核实结论的日志、截图、单据名称。\",\"required\":false,\"type\":\"textarea\"}]');
INSERT IGNORE INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F13','证据保全清单','[{\"label\":\"证据名称\",\"hint\":\"逐项填写保全的证据名称，如堡垒机操作日志、内存镜像。\",\"required\":true,\"type\":\"text\"},{\"label\":\"证据类型\",\"hint\":\"选择证据的类型。\",\"required\":true,\"type\":\"select\",\"options\":[\"日志\",\"样本文件\",\"内存镜像\",\"截图\",\"流量包\",\"其他\"]},{\"label\":\"来源对象\",\"hint\":\"证据来源的系统、主机、账号或设备。\",\"required\":true,\"type\":\"text\"},{\"label\":\"保全时间\",\"hint\":\"完成证据固定的时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"存放位置\",\"hint\":\"证据的存放介质、目录或平台位置。\",\"required\":true,\"type\":\"text\"},{\"label\":\"哈希值\",\"hint\":\"证据文件的 SHA256 或 MD5 值，用于完整性校验。\",\"required\":true,\"type\":\"text\"},{\"label\":\"保全人\",\"hint\":\"执行证据保全的人员姓名与岗位。\",\"required\":true,\"type\":\"text\"},{\"label\":\"完整性校验\",\"hint\":\"保全后是否完成哈希复核。\",\"required\":true,\"type\":\"select\",\"options\":[\"通过\",\"不通过\",\"未校验\"]}]');
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F2','网络安全事件上报表','[{\"label\":\"上报单位\",\"hint\":\"填写医院全称，与系统单位名称一致。\",\"required\":true,\"type\":\"text\"},{\"label\":\"事件类型\",\"hint\":\"如勒索病毒、DDoS 攻击、数据泄露、系统宕机等。\",\"required\":true,\"type\":\"select\",\"options\":[\"勒索病毒\",\"DDoS 攻击\",\"数据泄露\",\"系统宕机\",\"钓鱼邮件\",\"内网渗透\",\"其他\"]},{\"label\":\"事件等级\",\"hint\":\"按预案分为特别重大/重大/较大/一般，与研判结论一致。\",\"required\":true,\"type\":\"select\",\"options\":[\"特别重大\",\"重大\",\"较大\",\"一般\"]},{\"label\":\"发生时间\",\"hint\":\"事件实际发生时间；无法确认时填写首次发现时间并注明。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"发现时间\",\"hint\":\"首次发现事件的时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"受攻击系统\",\"hint\":\"被攻击或受影响的业务系统名称。\",\"required\":true,\"type\":\"text\"},{\"label\":\"IP/域名\",\"hint\":\"受攻击资产 IP、域名或端口，多个用顿号分隔。\",\"required\":true,\"type\":\"text\"},{\"label\":\"事件基本情况\",\"hint\":\"按「何时、何地、何事、如何发现」叙述事件经过。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"影响范围\",\"hint\":\"受影响业务系统、科室、患者服务与数据范围（演练虚拟数据）。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"已采取措施\",\"hint\":\"已执行的隔离、封堵、停机、备份等处置动作及时间。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"处置进展\",\"hint\":\"当前处置阶段与预计完成时间。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"下一步计划\",\"hint\":\"拟开展的溯源、恢复、整改等计划安排。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"报送人/联系电话\",\"hint\":\"报送人姓名 + 虚拟联系电话。\",\"required\":true,\"type\":\"text\"},{\"label\":\"上报对象\",\"hint\":\"勾选本次上报的全部接收单位，双报须两家同时勾选。\",\"required\":true,\"type\":\"multiselect\",\"options\":[\"市卫生健康局\",\"市网信办\",\"市网安大队\",\"院应急指挥部\"]},{\"label\":\"时限依据\",\"hint\":\"引用的上报时限条款，如重大事件 1 小时内。\",\"required\":true,\"type\":\"text\"},{\"label\":\"签发人\",\"hint\":\"负责签发本次上报材料的院领导或信息科负责人。\",\"required\":true,\"type\":\"text\"},{\"label\":\"回执编号\",\"hint\":\"接收单位反馈的回执编号，未取得可留空。\",\"required\":false,\"type\":\"text\"},{\"label\":\"报送时间\",\"hint\":\"实际报送时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F3','业务影响评估表','[{\"label\":\"受影响业务系统\",\"hint\":\"受影响的业务系统清单，多个用顿号分隔。\",\"required\":true,\"type\":\"text\"},{\"label\":\"业务中断起止时间\",\"hint\":\"格式如 2026-10-24 09:00 至 10:30；仍在中断填「持续中」。\",\"required\":true,\"type\":\"text\"},{\"label\":\"受影响科室\",\"hint\":\"受影响的临床、医技与窗口科室。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"受影响患者数（虚拟）\",\"hint\":\"仅填写演练虚拟数量，不得录入真实患者信息。\",\"required\":true,\"type\":\"text\"},{\"label\":\"建议等级\",\"hint\":\"按预案条款与影响评估给出建议事件等级，与上报表保持一致。\",\"required\":true,\"type\":\"select\",\"options\":[\"一般\",\"较大\",\"重大\",\"特别重大\"]},{\"label\":\"定级依据\",\"hint\":\"逐条写明影响系统、患者安全、数据量、扩散趋势四类依据及来源节点。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"患者安全影响\",\"hint\":\"评估本次事件对患者诊疗与生命安全的影响程度。\",\"required\":true,\"type\":\"select\",\"options\":[\"无影响\",\"潜在风险\",\"已影响诊疗\",\"危及生命安全\"]},{\"label\":\"关键业务中断比例\",\"hint\":\"按核心业务中断项数估算，如 60%（仅演练虚拟数据）。\",\"required\":true,\"type\":\"text\"},{\"label\":\"关键业务兜底方案\",\"hint\":\"如纸质处方、人工挂号收费、手工登记，注明启动条件。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"预计恢复时间\",\"hint\":\"预计业务恢复时间。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"评估人\",\"hint\":\"完成评估的医务/门诊负责人。\",\"required\":true,\"type\":\"text\"},{\"label\":\"评估时间\",\"hint\":\"评估完成时间。\",\"required\":true,\"type\":\"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F4','应急启动申请单','[{\"label\":\"事件摘要\",\"hint\":\"简述事件事实、等级与当前影响。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"建议响应等级\",\"hint\":\"按预案填写 Ⅰ级/Ⅱ级/Ⅲ级/Ⅳ级。\",\"required\":true,\"type\":\"select\",\"options\":[\"Ⅰ级\",\"Ⅱ级\",\"Ⅲ级\",\"Ⅳ级\"]},{\"label\":\"启动依据\",\"hint\":\"引用预案条款与研判结论。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"拟采取措施\",\"hint\":\"拟启动的响应措施与责任分工。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"申请部门/申请人\",\"hint\":\"提出启动申请的单位与人员。\",\"required\":true,\"type\":\"text\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F5','报案登记表','[{\"label\": \"报案单位\",\"hint\": \"报案单位全称。\",\"required\": true,\"type\": \"text\"},{\"label\": \"报案人/联系电话\",\"hint\": \"报案人姓名 + 虚拟联系电话。\",\"required\": true,\"type\": \"text\"},{\"label\": \"事件发现时间\",\"hint\": \"首次发现事件的时间。\",\"required\": true,\"type\": \"datetime\"},{\"label\": \"事件经过\",\"hint\": \"按时间顺序叙述发现与处置经过。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"受攻击系统\",\"hint\": \"受攻击系统名称。\",\"required\": true,\"type\": \"text\"},{\"label\": \"IP/域名\",\"hint\": \"涉案 IP、域名与端口。\",\"required\": true,\"type\": \"text\"},{\"label\": \"损失情况\",\"hint\": \"仅描述演练虚拟损失，如中断时长、受影响终端数。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"证据清单\",\"hint\": \"已固定的日志、样本摘要、截图等材料名称。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"证据保全\",\"key\": \"evidence_hold\",\"hint\": \"证据保全范围与方式（原始介质封存、哈希值、保全人）。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"报案方式\",\"hint\": \"选择实际采用的报案方式。\",\"required\": true,\"type\": \"select\",\"options\": [\"电话\",\"书面\",\"线上平台\"]},{\"label\": \"同步上报\",\"hint\": \"勾选同步报送的其他单位，未同步则选「未同步」。\",\"required\": false,\"type\": \"multiselect\",\"options\": [\"市卫生健康局\",\"市网信办\",\"未同步\"]},{\"label\": \"受理编号\",\"hint\": \"网安大队反馈的受理编号，未受理可留空。\",\"required\": false,\"type\": \"text\"},{\"label\": \"受理人\",\"key\": \"accept_officer\",\"hint\": \"受理民警姓名或警号，由受理单位填写。\",\"required\": false,\"type\": \"text\"},{\"label\": \"报案时间\",\"hint\": \"提交报案时间。\",\"required\": true,\"type\": \"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F6','舆情风险研判表','[{\"label\": \"监测渠道\",\"hint\": \"如社交媒体、论坛、短视频平台、上级通报。\",\"required\": true,\"type\": \"text\"},{\"label\": \"舆情摘要\",\"hint\": \"舆情主要内容与关键截图描述。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"传播趋势\",\"hint\": \"扩散速度、主要传播节点与当前热度。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"风险等级\",\"hint\": \"按研判结论填写 高/中/低。\",\"required\": true,\"type\": \"select\",\"options\": [\"高\",\"中\",\"低\"]},{\"label\": \"口径建议\",\"hint\": \"统一对外答复口径，不得透露真实患者信息。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"监管要求\",\"key\": \"regulator_requirement\",\"hint\": \"网信办提出的监管处置要求、整改时限与报送口径。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"是否需复查\",\"key\": \"review_required\",\"hint\": \"是否需要网信办后续复查。\",\"required\": true,\"type\": \"select\",\"options\": [\"需复查\",\"不需复查\"]},{\"label\": \"研判人\",\"hint\": \"参与研判的人员姓名。\",\"required\": true,\"type\": \"text\"},{\"label\": \"研判时间\",\"hint\": \"研判完成时间。\",\"required\": true,\"type\": \"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F7','业务恢复确认单','[{\"label\":\"HIS收费系统状态\",\"hint\":\"选择当前 HIS 收费系统的恢复状态。\",\"required\":true,\"type\":\"select\",\"options\":[\"正常\",\"隔离中\",\"灾备切换中\",\"恢复验证中\",\"已恢复\"]},{\"label\":\"医护工作站状态\",\"hint\":\"选择当前医护工作站的恢复状态。\",\"required\":true,\"type\":\"select\",\"options\":[\"正常\",\"隔离中\",\"灾备切换中\",\"恢复验证中\",\"已恢复\"]},{\"label\":\"电子病历系统状态\",\"hint\":\"选择当前电子病历系统的恢复状态。\",\"required\":true,\"type\":\"select\",\"options\":[\"正常\",\"隔离中\",\"灾备切换中\",\"恢复验证中\",\"已恢复\"]},{\"label\":\"临床检验系统状态\",\"hint\":\"选择当前临床检验系统的恢复状态。\",\"required\":true,\"type\":\"select\",\"options\":[\"正常\",\"隔离中\",\"灾备切换中\",\"恢复验证中\",\"已恢复\"]},{\"label\":\"医学影像系统状态\",\"hint\":\"选择当前医学影像系统的恢复状态。\",\"required\":true,\"type\":\"select\",\"options\":[\"正常\",\"隔离中\",\"灾备切换中\",\"恢复验证中\",\"已恢复\"]},{\"label\":\"办公OA系统状态\",\"hint\":\"选择当前办公OA系统的恢复状态。\",\"required\":true,\"type\":\"select\",\"options\":[\"正常\",\"隔离中\",\"灾备切换中\",\"恢复验证中\",\"已恢复\"]},{\"label\":\"恢复点时间\",\"hint\":\"实际使用的备份恢复点时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"RPO（数据丢失窗口）\",\"hint\":\"填写实际数据丢失时间窗口，如 15 分钟。\",\"required\":true,\"type\":\"text\"},{\"label\":\"RTO（恢复耗时）\",\"hint\":\"填写实际恢复耗时，如 45 分钟。\",\"required\":true,\"type\":\"text\"},{\"label\":\"恢复验证用例\",\"hint\":\"逐条写明 3 条业务验证用例及结果，如挂号、收费、发药各一条。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"二次加密检查\",\"hint\":\"恢复后检查是否出现新的加密写入。\",\"required\":true,\"type\":\"select\",\"options\":[\"未发现\",\"发现二次加密\",\"未检查\"]},{\"label\":\"未恢复系统\",\"hint\":\"列出仍未恢复的系统及原因，全部恢复填「无」。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"恢复情况说明\",\"hint\":\"逐项说明各系统恢复过程、验证结果及遗留问题。\",\"required\":false,\"type\":\"textarea\"},{\"label\":\"确认人\",\"hint\":\"业务与信息科双确认人员。\",\"required\":true,\"type\":\"text\"},{\"label\":\"确认时间\",\"hint\":\"确认完成时间。\",\"required\":true,\"type\":\"datetime\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F8','网络和数据安全事件反馈单','[{\"label\": \"受攻击系统\",\"hint\": \"被攻击或受影响的系统名称及版本，多个用顿号分隔。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"IP/域名\",\"hint\": \"受攻击资产 IP、域名、端口，多个用顿号分隔。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"事件基本情况\",\"hint\": \"简述发生时间、发现方式、攻击手法与事件等级。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"定级结论\",\"key\": \"incident_level\",\"hint\": \"按预案确认的事件等级。\",\"required\": true,\"type\": \"select\",\"options\": [\"Ⅰ级\",\"Ⅱ级\",\"Ⅲ级\",\"Ⅳ级\"]},{\"label\": \"事件影响范围\",\"hint\": \"受影响业务、科室、数据与患者服务范围（演练虚拟数据）。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"现场处置过程\",\"hint\": \"按时间顺序记录隔离、封堵、取证、恢复等动作及执行人。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"处置时间线\",\"key\": \"response_timeline\",\"hint\": \"按时间顺序记录关键处置节点与完成时刻。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"事件处置结果\",\"hint\": \"处置成效、业务恢复情况与残留风险。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"整改责任人\",\"key\": \"rectify_owner\",\"hint\": \"整改事项的责任部门与责任人。\",\"required\": true,\"type\": \"text\"},{\"label\": \"复测结论\",\"key\": \"retest_result\",\"hint\": \"恢复后复测结果、残留风险与是否通过。\",\"required\": true,\"type\": \"textarea\"},{\"label\": \"下一步整改及工作计划\",\"hint\": \"整改措施、责任部门、完成时限与复查安排。\",\"required\": true,\"type\": \"textarea\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `form_templates` (`id`, `name`, `fields`) VALUES ('F9','综合处置记录单','[{\"label\":\"处置对象\",\"hint\":\"写明本次处置的系统、主机或业务环节，仅演练虚拟数据。\",\"required\":true,\"type\":\"text\"},{\"label\":\"处置时间\",\"hint\":\"处置开始时间，精确到分钟。\",\"required\":true,\"type\":\"datetime\"},{\"label\":\"执行人\",\"hint\":\"实际执行处置的岗位与人员。\",\"required\":true,\"type\":\"text\"},{\"label\":\"处置动作\",\"hint\":\"按顺序写明做了什么，如关闭共享写入、隔离主机、切换手工流程。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"验证结果\",\"hint\":\"处置完成后的验证结论。\",\"required\":true,\"type\":\"select\",\"options\":[\"通过\",\"部分通过\",\"未通过\"]},{\"label\":\"证据材料\",\"hint\":\"支撑本次处置的日志、截图、单据名称。\",\"required\":true,\"type\":\"textarea\"},{\"label\":\"遗留风险\",\"hint\":\"尚未消除的风险与计划，无则填「无」。\",\"required\":false,\"type\":\"textarea\"},{\"label\":\"接收人确认\",\"hint\":\"接收处置结果的岗位与人员。\",\"required\":true,\"type\":\"text\"},{\"label\":\"审批结论\",\"hint\":\"仅启动审批节点填写，其余节点留空。\",\"required\":false,\"type\":\"select\",\"options\":[\"同意\",\"不同意\",\"有条件同意\"]},{\"label\":\"批准响应级别\",\"hint\":\"仅启动审批节点填写，须与研判等级一致。\",\"required\":false,\"type\":\"select\",\"options\":[\"Ⅰ级\",\"Ⅱ级\",\"Ⅲ级\",\"Ⅳ级\"]},{\"label\":\"启动时间\",\"hint\":\"仅启动审批节点填写，以指令下达时刻为准。\",\"required\":false,\"type\":\"datetime\"},{\"label\":\"授权范围\",\"hint\":\"仅启动审批节点填写，勾选本次启动授权的处置范围。\",\"required\":false,\"type\":\"multiselect\",\"options\":[\"停机\",\"断网隔离\",\"数据恢复\",\"对外上报\",\"对外发布口径\"]},{\"label\":\"审批人\",\"hint\":\"仅启动审批节点填写。\",\"required\":false,\"type\":\"text\"},{\"label\":\"启动令编号\",\"hint\":\"仅启动审批节点填写，可填演练虚拟编号。\",\"required\":false,\"type\":\"text\"}]') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `name`=VALUES(`name`), `fields`=VALUES(`fields`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('DSS01-cac-12-1','S01','task','单系统事件先院内处置，达到上报标准再报','达标再上报','市网信办','',60,'','','未达上报标准不必上报，可减少监管打扰；标准判断需要时间，可能错过 1 小时时限。','[]',42,'先看标准再决定。','单系统,后上报,时限','研判分级','[]','null',0,'distractor',8,'','[]',2271,433,'S01-13','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
