INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S01-2','S01','parallel','10 分钟内拉出受影响终端清单','核实影响范围','信息科值班员','',10,'F1','','按网段与科室拉清单，分已加密、疑似、正常三类，标出仍在加密的主机，报系统管理员。','[]',1,'先查共享目录访问告警，再逐网段核对主机名与科室；清单要能定位到人。','终端清单,网段,仍在加密,受影响主机','告警核实','[]','[{\"type\":\"处置记录\",\"name\":\"受影响终端清单\",\"note\":\"含主机名、科室、已加密/疑似/正常\"},{\"type\":\"附件截图\",\"name\":\"共享目录访问告警截图\",\"note\":\"含最近写入时间\"}]',1,'correct',7,'系统管理员','[\"S01-1\"]',536,489,NULL,'before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
