INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S01-4','S01','parallel','核对恢复点并抽验备份可读','数据备份校验','数据安全管理员','',15,'F11','','核对最近 3 个恢复点时间与大小，确认 RPO；抽 1 个非核心库验证可读，登记不可用备份。','[]',3,'先看备份完成时间与容量，再抽验表结构可读；不在生产库做覆盖恢复。','恢复点,RPO,可读性,备份校验','告警核实','[]','[{\"type\":\"处置记录\",\"name\":\"备份校验记录\",\"note\":\"含恢复点时间、抽验库名与结论\"},{\"type\":\"附件截图\",\"name\":\"备份任务状态截图\",\"note\":\"含最近 3 次备份完成时间\"}]',1,'correct',7,'系统管理员','[\"S01-1\"]',536,828,NULL,'before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S01-5','S01','task','预警研判：确认重大（Ⅱ级）事件','预警研判','系统管理员','',15,'F3','','汇总核实、隔离、备份三路结果，按预案条款比对影响系统、患者安全、数据量与扩散趋势，形成重大（Ⅱ级）意见。','[]',4,'先列事实再对条款；每条定级依据注明来源节点与时间，报信息科负责人。','定级依据,患者安全,扩散趋势,Ⅱ级','研判分级','[]','[{\"type\":\"表单文书\",\"name\":\"定级意见\",\"note\":\"含四类依据与建议等级\"},{\"type\":\"处置记录\",\"name\":\"影响评估记录\",\"note\":\"含系统、科室、患者安全影响\"}]',1,'correct',7,'信息科负责人','[\"S01-2\",\"S01-3\",\"S01-4\"]',841,656,NULL,'before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S01-6','S01','report','向院应急指挥部报告并建议启动预案','院内应急上报','信息科负责人','',10,'F4','','10 分钟内出一页简报：事件、影响、已采取措施、请求启动Ⅱ级；口头先报，书面随后，不等外部回复。','[]',5,'先报结论与请求，再报依据；写明需指挥部批准的事项。','简报,启动建议,Ⅱ级','上报审批','[]','[{\"type\":\"上报材料\",\"name\":\"上报材料/审批记录\",\"note\":\"含报送时间与口头报告对象\"},{\"type\":\"表单文书\",\"name\":\"启动申请单\",\"note\":\"含事件摘要、建议等级与申请部门\"}]',1,'correct',6,'院应急指挥部','[\"S01-5\"]',NULL,NULL,NULL,'before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S01-7','S01','report','院应急指挥部批准启动Ⅱ级应急响应','启动应急响应','院应急指挥部','',10,'F9','','批准启动Ⅱ级：明确响应级别、启动时间、授权范围（停机、断网、数据恢复、对外上报），形成启动令。','[]',6,'先确认定级依据齐全，再批授权范围；启动时间以指令下达时刻为准并通知到岗。','启动令,授权范围,响应级别,启动时间','启动预案','[]','[{\"type\":\"表单文书\",\"name\":\"Ⅱ级响应启动令\",\"note\":\"含批准人、启动时间与授权范围\"},{\"type\":\"处置记录\",\"name\":\"通知到岗记录\",\"note\":\"含通知对象与时间\"}]',1,'correct',6,'信息科负责人、医务处、网络安全管理员、系统管理员','[\"S01-6\"]',1418,657,NULL,'before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
