INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S02-1','S02','alert','异常账号 10 分钟内多地同时登录告警','异常登录告警','信息科值班员','',5,'','','账号审计平台发现同一运维账号在院内办公网与境外地址短时间内同时登录，涉及堡垒机与核心业务系统，账号可能已被盗用。','[]',0,'先看告警时间、源 IP 归属地与登录终端，核对是否本人操作；不要重启主机或先删日志。','异常登录,多地登录,堡垒机,境外','告警核实',NULL,'[{\"type\":\"附件截图\",\"name\":\"告警界面截图\",\"note\":\"含告警时间、账号、源 IP 与登录终端\"},{\"type\":\"处置记录\",\"name\":\"核实处置记录\",\"note\":\"含核实人、核实时间与结论\"}]',1,'correct',0,'信息科值班员','[]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
