INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S02-3','S02','task','预警研判：确认较大（Ⅲ级）事件','研判定级Ⅲ级','信息科负责人','',15,'F3','','汇总失陷账号、登录来源、横向痕迹与数据外泄风险，对照院预案分级标准研判为较大（Ⅲ级），明确是否已造成电子病历数据外泄。','[]',2,'先列事实再对条款；按影响系统、数据、患者安全、扩散趋势四类依据写明来源节点与时间，报院应急指挥部。','定级依据,Ⅲ级,数据外泄,扩散趋势','研判分级',NULL,'[{\"type\":\"表单文书\",\"name\":\"业务影响评估表\",\"note\":\"含四类定级依据与建议等级\"},{\"type\":\"处置记录\",\"name\":\"定级研判记录\",\"note\":\"含研判人、时间与结论\"}]',1,'correct',8,'院应急指挥部','[\"S02-2\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S02-4','S02','report','向院应急指挥部报告并建议启动预案','报告建议启动','信息科负责人','',10,'F4','','10 分钟内出一页简报：事件等级（Ⅲ级）、失陷账号、渗透路径初判、已采取措施与处置建议，申请启动Ⅲ级响应。','[]',3,'先报结论与请求，再报依据；写明需指挥部批准的事项，不等外部回复。','Ⅲ级,影响范围,处置建议,启动','上报审批',NULL,'[{\"type\":\"表单文书\",\"name\":\"应急启动申请单\",\"note\":\"含事件摘要、建议等级与启动依据\"},{\"type\":\"上报材料\",\"name\":\"上报记录\",\"note\":\"含报告时间与接收人\"}]',1,'correct',7,'院应急指挥部','[\"S02-3\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S02-5','S02','report','院应急指挥部批准启动Ⅲ级应急响应','批准启动Ⅲ级','院应急指挥部','',10,'F9','','批准启动Ⅲ级：明确响应级别、启动时间、授权范围（停用账号、隔离主机、取证、对外上报），形成启动令并通知到岗。','[]',4,'先确认定级依据齐全，再批授权范围；启动时间以指令下达时刻为准。','响应级别,授权范围,启动时间,启动令','启动预案',NULL,'[{\"type\":\"表单文书\",\"name\":\"Ⅲ级响应启动令\",\"note\":\"含批准人、启动时间与授权范围\"},{\"type\":\"处置记录\",\"name\":\"通知到岗记录\",\"note\":\"含通知对象与时间\"}]',1,'correct',8,'系统管理员、网络安全管理员、信息科负责人','[\"S02-4\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
