INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S03-10','S03','task','溯源攻击源并封禁 IP','溯源封禁','网络安全管理员','',20,'F9','','输出攻击源 IP 清单、归属与峰值时间线；封禁前核对合作方与医保专线出口，按段封禁并保留封禁前后设备日志，记录解封条件。','[]',10,'封禁前确认非医院合作方出口 IP。','溯源,封禁,IP,攻击源','隔离处置',NULL,'[{\"type\":\"操作日志\",\"name\":\"网络设备/防火墙操作日志\",\"note\":\"\"},{\"type\":\"处置记录\",\"name\":\"隔离处置记录\",\"note\":\"\"}]',1,'correct',8,'系统管理员','[\"S03-8\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S03-11','S03','task','向市网安大队报案并提交证据材料','报案取证','信息科负责人','',15,'F5','','不等待外部意见，先行向市网安大队报案：提交事件经过、受影响系统、峰值流量与源 IP 清单、已保全证据（抓包/日志/哈希），取得受理编号，按要求补充材料。','[]',11,'先报案再补材料；书面材料与证据清单同步提交，保留受理编号。','网安大队,报案,证据,材料','对外上报',NULL,'[{\"type\":\"样本摘要\",\"name\":\"样本/日志摘要归档\",\"note\":\"\"},{\"type\":\"附件\",\"name\":\"取证材料附件\",\"note\":\"\"},{\"type\":\"上报材料\",\"name\":\"上报材料/审批记录\",\"note\":\"\"},{\"type\":\"表单文书\",\"name\":\"报告/审批表单\",\"note\":\"\"},{\"type\":\"报案材料\",\"name\":\"报案材料/对接记录\",\"note\":\"\"},{\"type\":\"上报材料\",\"name\":\"对外口径/舆情回应\",\"note\":\"\"}]',1,'correct',7,'院应急指挥部','[\"S03-5\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
