INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S03-14','S03','task','证据保全：抓包、清洗设备日志与源 IP 清单','证据保全','网络安全管理员','',20,'F13','','在清洗与封禁前固定证据：镜像/抓包留存攻击流量，导出清洗设备与防火墙日志、源 IP 清单与时间线，逐项生成哈希并登记 F13 证据保全清单，明确存放位置与保管人。','[]',6,'先固定证据再清洗：抓包与设备日志交不同经办人复核，生成哈希清单。','抓包,日志,源IP,哈希,证据保全','取证留痕','[]','[{\"type\": \"抓包文件\", \"name\": \"攻击流量抓包（pcap）\", \"note\": \"含峰值时段，记录起止时间与采集点\"}, {\"type\": \"操作日志\", \"name\": \"清洗设备/防火墙日志\", \"note\": \"导出清洗策略下发前后的完整日志\"}, {\"type\": \"证据清单\", \"name\": \"源 IP 清单及归属\", \"note\": \"含峰值时间线与合作方/医保专线核对结果\"}, {\"type\": \"表单文书\", \"name\": \"证据保全清单（F13）\", \"note\": \"含哈希值、存放位置、保全人与完整性校验\"}]',1,'correct',8,'院应急指挥部','[\"S03-5\"]',NULL,NULL,NULL,'before',NULL) ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
