INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S04-1','S04','alert','员工收到钓鱼邮件告警','钓鱼告警','信息科值班员','',5,'','','统计收件人数、点击人数与提交凭据人数，记录首封钓鱼邮件到达时间、发件人与涉及科室，为研判提供三层数据。','[]',0,'统计收件人数、点击人数与提交凭据人数。','钓鱼邮件,收件人数,点击人数,提交凭据,首封时间','告警核实',NULL,'[{\"type\":\"附件截图\",\"name\":\"钓鱼邮件告警截图\",\"note\":\"含收件时间、主题、发件人与涉及科室\"},{\"type\":\"处置记录\",\"name\":\"收件/点击/提交凭据人数统计\",\"note\":\"三层人数分别列明并注明数据来源\"},{\"type\":\"样本摘要\",\"name\":\"首封邮件样本摘要\",\"note\":\"保留邮件头与仿冒域名\"}]',1,'correct',0,'信息科值班员','[]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
