INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S04-2','S04','task','核实邮件内容与点击人员','邮件核实','信息科值班员','',10,'F12','','核实仿冒域名、发件人、附件类型、点击名单与已提交凭据名单，判断是否已有终端失陷，形成可判定的核实结论。','[]',1,'优先排查已提交凭据的账号，按泄露处置。','仿冒域名,发件人,附件类型,点击名单,提交凭据,失陷','告警核实',NULL,'[{\"type\":\"表单文书\",\"name\":\"事件核实单（F12）\",\"note\":\"含发现渠道、仿冒域名、三层人数与失陷判断\"},{\"type\":\"处置记录\",\"name\":\"点击与提交凭据人员名单\",\"note\":\"按姓名、科室、账号逐条列明\"},{\"type\":\"附件截图\",\"name\":\"邮件原文与邮件头截图\",\"note\":\"保留发件人IP、Return-Path与仿冒域名\"}]',1,'correct',8,'信息科负责人','[\"S04-1\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
