INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S05-8','S05','task','业务兜底：六大环节全面启用手工流程','六环节兜底','医务处','',25,'F9','','六大环节（挂号、收费、门诊、住院、检验、药房）全面启用手工流程，记录各环节切换时间、单据编号规则与责任人。','[]',8,'系统恢复 1 小时内门诊手工单集中送收费处结算；住院电子病历 24 小时内完成补录。','兜底,纸质,手工,六大环节','业务兜底',NULL,'[{\"type\":\"处置记录\",\"name\":\"备份/恢复操作记录\",\"note\":\"\"},{\"type\":\"附件截图\",\"name\":\"业务恢复验证截图\",\"note\":\"\"},{\"type\":\"处置记录\",\"name\":\"通知发布记录\",\"note\":\"\"},{\"type\":\"附件截图\",\"name\":\"预警/兜底界面截图\",\"note\":\"\"}]',1,'correct',7,'收费窗口','[\"S05-5\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S05-9','S05','task','切换备用存储或降级运行','存储切换','系统管理员','',20,'F9','','切换前确认备用存储容量与数据同步状态并完成取证，记录切换时间点、切换范围与回退条件。','[]',9,'切换前确认备用存储容量与数据同步状态。','切换,备用,降级,存储','处置恢复',NULL,'[{\"type\":\"处置记录\",\"name\":\"备份/恢复操作记录\",\"note\":\"\"},{\"type\":\"附件截图\",\"name\":\"业务恢复验证截图\",\"note\":\"\"}]',1,'correct',7,'系统管理员','[\"S05-5\",\"S05-15\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-1','S06','alert','互联网出现患者信息售卖帖告警','泄露告警','信息科值班员','',10,'','','互联网平台出现患者信息售卖帖。记录帖子URL、发布时间、截图与截图哈希（SHA-256）、疑似泄露字段名与样本量级；只登记字段结构与数量，不摘录任何患者个人信息。','[]',0,'立即截图固证（含URL、发布时间与页面完整截图）并计算哈希；禁止与发帖人私下接触，禁止先行删帖或转发样本。','泄露,截图,哈希,帖子,固证','告警核实',NULL,'[{\"type\":\"附件截图\",\"name\":\"售卖帖页面截图\",\"note\":\"含URL、发布时间与页面全貌\"},{\"type\":\"附件\",\"name\":\"截图哈希清单\",\"note\":\"SHA-256 值，仅记录文件哈希\"},{\"type\":\"处置记录\",\"name\":\"告警核实记录\",\"note\":\"含发现时间、发现渠道与核实人\"}]',1,'correct',0,'信息科值班员','[]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-10','S06','task','向市网安大队报案并提交证据材料','报案取证','信息科负责人','',15,'F5','','确认数据泄露后即向市网安大队报案并提交证据材料；报案不以卫健局、网信办意见为前置条件，材料不全可先报案后补。','[]',9,'先报案后补材料，不得等外部意见或删帖结果；报案信息只写字段名与结构，不列患者个人信息。','报案,网安,证据,受理,立案','对外上报',NULL,'[{\"type\":\"表单文书\",\"name\":\"报案登记表\",\"note\":\"含事件经过、字段清单与证据目录\"},{\"type\":\"报案材料\",\"name\":\"报案材料与证据目录\",\"note\":\"仅字段名与结构，不含患者个人信息\"},{\"type\":\"上报材料\",\"name\":\"受理回执\",\"note\":\"含受理编号与受理人\"}]',1,'correct',8,'院应急指挥部','[\"S06-5\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-11','S06','report','统一对外口径与舆情回应','舆情回应','院应急指挥部','',15,'F9','','在网信办审核口径后，由院发言人统一对外发布事件口径与进展；未经审批不得披露事件细节或患者信息。','[]',10,'口径须经法务与网信办审核；只发布已核实事实，不披露患者个人信息。','舆情,口径,审批,发布,发言人','协同沟通',NULL,'[{\"type\":\"表单文书\",\"name\":\"对外口径审批单\",\"note\":\"含法务与网信办审核意见\"},{\"type\":\"处置记录\",\"name\":\"发布记录\",\"note\":\"含发布时间、渠道与发言人\"}]',1,'correct',8,'院应急指挥部','[\"S06-6\",\"S06-7\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-12','S06','task','患者告知与法律评估','患者告知','医务处','',20,'F9','','按影响分级确定告知范围（涉及患者及家属），采用短信、电话或公告等方式告知泄露字段、可能影响与求助渠道；告知内容经法务审核并留痕（范围、方式、法务意见、时间）。','[]',11,'告知不得等外部统一口径；先告知受影响患者，再统一对外发布；告知记录只写字段名与结构。','告知,范围,方式,法务,患者','协同沟通',NULL,'[{\"type\":\"处置记录\",\"name\":\"患者告知记录\",\"note\":\"含告知范围、方式、时间与执行人\"},{\"type\":\"表单文书\",\"name\":\"法务审核意见\",\"note\":\"含告知内容与合规结论\"}]',1,'correct',8,'院应急指挥部','[\"S06-6\",\"S06-7\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
