INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-14','S06','report','市网安大队受理回执与取证要求确认（院应急指挥部代收）','报案回执','市网安大队','',15,'','','市网安大队受理报案后反馈受理编号、受理人与取证要求；外部单位只读查看，由院应急指挥部代收并回填，形成受理回执与取证清单。','[]',12,'外部单位只提供只读入口，不参与处置提交；回执由院应急指挥部代收，取证材料按清单补充。','回执,受理,立案,取证要求','对外上报','','[{\"type\":\"上报材料\",\"name\":\"市网安大队受理回执\",\"note\":\"含受理编号、受理人与受理时间\"},{\"type\":\"处置记录\",\"name\":\"取证要求清单\",\"note\":\"含补充材料、联系人与时限\"}]',1,'correct',6,'院应急指挥部','[\"S06-10\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-15','S06','end','复盘总结与整改闭环','复盘整改','信息科负责人','',15,'','','复盘事件时间线、证据完整性、告知覆盖率、上报与报案闭环情况，形成整改项、责任人与完成时限，并归档总结报告。','[]',14,'复盘只引用字段名与结构，不写入患者个人信息；整改项须明确责任人与时限。','复盘,整改,时限,闭环,报告','应急结束','','[{\"type\":\"上报材料\",\"name\":\"复盘总结报告\",\"note\":\"含时间线、问题清单与整改计划\"},{\"type\":\"处置记录\",\"name\":\"整改清单\",\"note\":\"含责任人、时限与复查安排\"}]',1,'correct',6,'院应急指挥部','[\"S06-13\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-2','S06','task','核实泄露样本与数据量级','样本核实','信息科值班员','',20,'F12','','仅比对脱敏字段（字段名、类型、编码规则），核定泄露数据条数、涉及字段、时间范围与是否含身份证号、病历号等敏感标识；不得复制、转存或外发原始样本。','[]',1,'先固化样本哈希，再在隔离环境比对；只记录字段结构与统计量，不记录患者个人信息。','核实,样本,脱敏,条数,字段','告警核实',NULL,'[{\"type\":\"样本摘要\",\"name\":\"脱敏样本字段清单\",\"note\":\"仅字段名、类型与条数，不含患者个人信息\"},{\"type\":\"处置记录\",\"name\":\"数据量级核实记录\",\"note\":\"含条数、时间范围与敏感标识\"}]',1,'correct',8,'信息科负责人','[\"S06-1\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
