INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-7','S06','report','同时报市网信办','报网信办','信息科负责人','',15,'F2','','按1小时时限向市网信办报告事件等级、泄露数据范围与舆情情况，样本先固定哈希后提交。','[]',6,'先固定样本再对外提交；不得等删帖完成再报。','上报,网信,1小时,舆情,回执','对外上报',NULL,'[{\"type\":\"表单文书\",\"name\":\"网络安全事件上报表\",\"note\":\"含上报对象、时限依据与报送时间\"},{\"type\":\"上报材料\",\"name\":\"市网信办上报回执\",\"note\":\"含接收人与回执编号\"},{\"type\":\"样本摘要\",\"name\":\"样本哈希清单\",\"note\":\"外发前已固定哈希\"}]',1,'correct',8,'信息科负责人、医务处','[\"S06-5\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
INSERT INTO `script_nodes` (`id`, `scenario_id`, `type`, `title`, `short_title`, `target`, `time`, `timeout`, `form`, `att`, `descr`, `branches`, `seq`, `guide`, `keywords`, `action`, `wrong`, `evidence_req`, `required`, `flow_type`, `score`, `receiver`, `deps`, `pos_x`, `pos_y`, `anchor_id`, `release_timing`, `parallel_desc`) VALUES ('S06-8','S06','task','关闭外泄接口并加固数据权限','接口加固','网络安全管理员','',20,'F9','','在完成证据固定后关闭外泄接口并加固数据权限：留存关闭前访问日志，排查第三方运维账号与测试环境接口，复核最小权限。','[]',8,'先取证后关闭；关闭前导出并校验访问日志，避免破坏证据链。','接口,权限,加固,访问日志,第三方','处置恢复',NULL,'[{\"type\":\"处置记录\",\"name\":\"接口关闭记录\",\"note\":\"含关闭时间、接口清单与执行人\"},{\"type\":\"操作日志\",\"name\":\"关闭前访问日志\",\"note\":\"含访问账号与时间范围\"},{\"type\":\"处置记录\",\"name\":\"权限加固清单\",\"note\":\"含第三方运维与测试接口排查结果\"}]',1,'correct',8,'院应急指挥部','[\"S06-5\",\"S06-9\"]',NULL,NULL,'','before','') ON DUPLICATE KEY UPDATE `id`=VALUES(`id`), `scenario_id`=VALUES(`scenario_id`), `type`=VALUES(`type`), `title`=VALUES(`title`), `short_title`=VALUES(`short_title`), `target`=VALUES(`target`), `time`=VALUES(`time`), `timeout`=VALUES(`timeout`), `form`=VALUES(`form`), `att`=VALUES(`att`), `descr`=VALUES(`descr`), `branches`=VALUES(`branches`), `seq`=VALUES(`seq`), `guide`=VALUES(`guide`), `keywords`=VALUES(`keywords`), `action`=VALUES(`action`), `wrong`=VALUES(`wrong`), `evidence_req`=VALUES(`evidence_req`), `required`=VALUES(`required`), `flow_type`=VALUES(`flow_type`), `score`=VALUES(`score`), `receiver`=VALUES(`receiver`), `deps`=VALUES(`deps`), `pos_x`=VALUES(`pos_x`), `pos_y`=VALUES(`pos_y`), `anchor_id`=VALUES(`anchor_id`), `release_timing`=VALUES(`release_timing`), `parallel_desc`=VALUES(`parallel_desc`);
